    // ── Subtitles ───────────────────────────────────────────────────────────
    async function loadSubtitles() {
        if (!state.currentProject) return;
        const pid = state.currentProject.id;
        const picker = document.getElementById('subtitleLang');
        try {
            const langs = await api(`/projects/${pid}/languages`).catch(() => null)
                || await api(`/projects/${pid}/subtitles/languages`);
            const list = langs.languages || [];
            const chosen = picker.value || list[0] || 'en';
            /*
             * The language a project already has, plus the one being viewed.
             * Rebuilt only when the set changed, or re-rendering resets the
             * picker mid-selection.
             */
            const want = [...new Set([...list, chosen])];
            if (picker.dataset.langs !== want.join(',')) {
                picker.innerHTML = want.map(l =>
                    `<option value="${esc(l)}"${l === chosen ? ' selected' : ''}>${esc(l)}</option>`).join('');
                picker.dataset.langs = want.join(',');
            }
            const data = await api(`/projects/${pid}/subtitles?language=${encodeURIComponent(chosen)}`);
            state.subtitleRows = data.subtitles || [];
            /*
             * The shot list, for the cue's own shot. A caption belongs to the
             * shot it plays over, and the route has always taken a shot_id —
             * without a picker the field could only be set by curl, which is
             * the gap this whole page exists to close.
             */
            if (!SUB_SHOTS.length) {
                try {
                    const sl = await api(`/projects/${pid}/shotlist`);
                    SUB_SHOTS = sl.shots || [];
                } catch (_) { SUB_SHOTS = []; }
            }
            renderSubtitles(state.subtitleRows);
        } catch (err) {
            document.getElementById('subtitleList').innerHTML =
                `<p class="text-sm text-muted">Could not read the subtitles: ${esc(err.message)}</p>`;
        }
    }

    let SUB_SHOTS = [];

    const subTime = ms => {
        const t = Math.max(0, Number(ms) || 0) / 1000;
        return `${Math.floor(t / 60)}:${String((t % 60).toFixed(1)).padStart(4, '0')}`;
    };

    function renderSubtitles(rows) {
        const host = document.getElementById('subtitleList');
        if (!rows.length) {
            host.innerHTML = '<p class="text-sm text-muted">No cues in this language yet.</p>';
            return;
        }
        host.innerHTML = rows.map(r => `
            <div class="card" style="margin-bottom:6px;">
                <div class="flex-between" style="gap:8px;flex-wrap:wrap;min-width:0;">
                    <div style="min-width:0;">
                        <div class="text-sm text-muted">${subTime(r.start_ms)} &rarr; ${subTime(r.end_ms)}</div>
                        <strong>${esc(r.text || '')}</strong>
                        <div class="tag-row" style="margin-top:4px;">
                            ${r.speaker ? `<span class="tag">${esc(r.speaker)}</span>` : ''}
                            <span class="tag">${esc(r.position || 'bottom')}</span>
                            ${r.is_cc ? '<span class="badge">CC</span>' : ''}
                        </div>
                    </div>
                    <div class="card-actions">
                        <button class="btn btn-secondary btn-sm" onclick="openSubtitle('${r.id}')">Edit</button>
                        <button class="btn btn-secondary btn-sm" onclick="deleteSubtitle('${r.id}')">Delete</button>
                    </div>
                </div>
            </div>`).join('');
    }

    function openSubtitle(id) {
        const r = id ? (state.subtitleRows || []).find(x => x.id === id) || {} : {};
        const lang = (document.getElementById('subtitleLang') || {}).value || 'en';
        showModalHtml('subtitleModal', `
            <div class="modal-header">
                <h3>${id ? 'Edit cue' : 'New cue'}</h3>
                <button class="modal-close" onclick="closeModal('subtitleModal')">&times;</button>
            </div>
            <div class="modal-body">
                <div class="form-group"><label>Text</label>
                    <textarea id="subText" data-field="text" rows="2" maxlength="1000">${esc(r.text || '')}</textarea></div>
                <div class="form-group"><label>Start (seconds)</label>
                    <input type="number" id="subStart" data-field="start_ms" min="0" step="0.01"
                           value="${((r.start_ms || 0) / 1000).toFixed(2)}"></div>
                <div class="form-group"><label>End (seconds)</label>
                    <input type="number" id="subEnd" data-field="end_ms" min="0" step="0.01"
                           value="${((r.end_ms || 0) / 1000).toFixed(2)}"></div>
                <div class="form-group"><label>Language</label>
                    <input type="text" id="subLang" data-field="language" maxlength="10" value="${esc(r.language || lang)}"
                           placeholder="e.g. en, fr, pt-BR"></div>
                <div class="form-group"><label>Speaker</label>
                    <input type="text" id="subSpeaker" data-field="speaker" maxlength="100" value="${esc(r.speaker || '')}"
                           placeholder="Who is talking — shown in closed captions"></div>
                <div class="form-group"><label>Position</label>
                    <select id="subPosition" data-field="position">
                        ${['bottom', 'top', 'middle'].map(v =>
                            `<option value="${v}"${(r.position || 'bottom') === v ? ' selected' : ''}>${v}</option>`).join('')}
                    </select>
                    <span class="text-sm text-muted">Where on screen it sits. Top is for a cue that would cover a face.</span></div>
                <div class="form-group"><label>Shot</label>
                    <select id="subShot" data-field="shot_id">
                        <option value="">Not tied to a shot</option>
                        ${SUB_SHOTS.map(sh => `<option value="${esc(sh.id)}"${sh.id === r.shot_id ? ' selected' : ''}>`
                            + `${esc(sh.shot_code || sh.id)}</option>`).join('')}
                    </select>
                    <span class="text-sm text-muted">Optional. Tying a cue to its shot is what lets a
                        re-cut carry the caption with the picture instead of leaving it at a timecode.</span></div>
                <div class="form-group"><label>Style</label>
                    <input type="text" id="subStyle" data-field="style" maxlength="500" value="${esc(r.style || '')}"></div>
                <div class="form-group">
                    <label><input type="checkbox" id="subCC" data-field="is_cc" ${r.is_cc ? 'checked' : ''}>
                        Closed caption</label>
                    <span class="text-sm text-muted">A caption describes sound as well as speech; a subtitle carries the words only.</span></div>
            </div>
            <div class="modal-footer">
                <button class="btn btn-secondary" onclick="closeModal('subtitleModal')">Cancel</button>
                <button class="btn btn-primary" onclick="saveSubtitle(${id ? `'${id}'` : 'null'})">Save</button>
            </div>`);
    }

    async function saveSubtitle(id) {
        const v = i => (document.getElementById(i) || {}).value;
        const body = {
            text: v('subText'),
            start_ms: Math.round((Number(v('subStart')) || 0) * 1000),
            end_ms: Math.round((Number(v('subEnd')) || 0) * 1000),
            language: v('subLang') || 'en',
            speaker: v('subSpeaker'),
            position: v('subPosition'),
            style: v('subStyle'),
            shot_id: v('subShot') || null,
            is_cc: !!(document.getElementById('subCC') || {}).checked,
        };
        if (!body.text) return setStatus('A cue needs its text');
        // Refused here rather than at the route, because a zero-length cue is
        // invisible in playback and looks like the save failed.
        if (body.end_ms <= body.start_ms) return setStatus('A cue has to end after it starts');
        try {
            await api(id ? `/subtitles/${id}` : `/projects/${state.currentProject.id}/subtitles`,
                { method: id ? 'PUT' : 'POST', body: JSON.stringify(body) });
            closeModal('subtitleModal');
            setStatus(id ? 'Cue updated' : 'Cue added');
            loadSubtitles();
        } catch (err) { setStatus('Error: ' + err.message); }
    }

    async function deleteSubtitle(id) {
        if (!confirm('Remove this cue?')) return;
        try { await api(`/subtitles/${id}`, { method: 'DELETE' }); loadSubtitles(); setStatus('Cue removed'); }
        catch (err) { setStatus('Error: ' + err.message); }
    }

    function exportSubtitles(fmt) {
        const lang = (document.getElementById('subtitleLang') || {}).value || 'en';
        // Opened rather than fetched: the route answers with a file, and the
        // artifact sandbox aside, a browser download is what a person wants here.
        window.open(`${API_BASE}/projects/${state.currentProject.id}/subtitles/export/${fmt}`
            + `?language=${encodeURIComponent(lang)}`, '_blank');
    }
